import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    words = input_data[1:n+1]

    MOD = 10**9 + 7

    def get_variants(s):
        variants = set()
        l = len(s)
        for i in range(l):
            variants.add(s[:i] + s[i+1:])
        return sorted(variants)

    prev_variants = []
    if n > 0:
        prev_variants = get_variants(words[0])

    count = [1] * len(prev_variants)

    for i in range(1, n):
        curr_variants = get_variants(words[i])
        new_count = [0] * len(curr_variants)

        j = 0
        for k in range(len(curr_variants)):
            c = curr_variants[k]
            while j < len(prev_variants) and prev_variants[j] <= c:
                j += 1
            if j > 0:
                new_count[k] = sum(count[:j]) % MOD

        prev_variants = curr_variants
        count = new_count

    result = sum(count) % MOD
    print(result)

if __name__ == "__main__":
    solve()
